import java.io.*;
import java.util.Arrays;

public class Main {

    private static String nextNonEmpty(BufferedReader br) throws IOException {
        String s = br.readLine();
        while (s != null && s.trim().isEmpty()) s = br.readLine();
        return s == null ? "" : s.trim();
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        StringTokenizer st = new StringTokenizer(nextNonEmpty(br));
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        String password = nextNonEmpty(br);

        char[][] words = new char[m][];
        for (int i = 0; i < m; i++) {
            words[i] = nextNonEmpty(br).toCharArray();
            Arrays.sort(words[i]); // ordem lexicográfica das opções desta posição
        }

        long p = Long.parseLong(nextNonEmpty(br));

        // CAP: qualquer peso real >= CAP é maior que r (r = P-1 <= 10^9 - 1)
        final long CAP = 2_000_000_000L;

        // pow[i] = K^(m-i) limitado a CAP
        long[] pow = new long[m + 1];
        pow[m] = 1;
        for (int i = m; i >= 1; i--) {
            long v = pow[i] * k; // <= CAP * 26, sem overflow
            pow[i - 1] = Math.min(v, CAP);
        }

        // Para a j-ésima letra borrada (0-based), o peso é K^(m-1-j) = pow[j+1]
        long r = p - 1;
        char[] chosen = new char[m];
        for (int j = 0; j < m; j++) {
            long w = pow[j + 1];
            int idx = (int) (r / w);
            if (idx >= k) idx = k - 1; // proteção contra entrada inválida
            r %= w;
            chosen[j] = words[j][idx];
        }

        StringBuilder sb = new StringBuilder(n);
        int j = 0;
        for (int i = 0; i < n; i++) {
            char c = password.charAt(i);
            if (c == '#') {
                sb.append(chosen[j++]);
            } else {
                sb.append(c);
            }
        }

        System.out.println(sb);
    }
}
